import type {AddressInfo} from 'node:net';
import type {WebSocket} from 'ws';
import {createHalEngine} from './config.js';
import type {HalEngine, HalEngineConfig} from './config.js';
import type {HalServerOptions} from './transport/createServer.js';
import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
import {MongoSessionStore} from './infrastructure/stores/mongo/mongoSessionStore.js';
import {fakeCollection} from './infrastructure/stores/mongo/mongoTestSupport.js';
import {createChatOrchestrator} from './orchestration/chatOrchestrator.js';
import {PromptBuilder} from './infrastructure/builders/promptBuilder.js';
import {setLogger} from './shared/logger.js';
import type {AIProvider} from './types/ai.js';
import type {SessionListOptions, SessionStore} from './types/sessionStore.js';
import {connectClient, deferred, startEngineWith, stopEngines} from './transport/wsTestSupport.js';

interface WireSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

interface WireFrame {
  type: string;
  code?: string;
  message?: string;
  timestamp?: number;
  sessionId?: string;
  resumed?: boolean;
  entryCount?: number;
  conversations?: WireSummary[];
  index?: number;
  entry?: {role: string; content?: string};
}

interface RecordedCall {
  userId: string | number;
  options: SessionListOptions | undefined;
}

const engines: HalEngine[] = [];

describe('delivering a user conversation list over WebSocket', () => {
  afterEach(async () => {
    setLogger();
    await stopAll();
  });

  it("returns the authenticated user's conversations newest first as ISO summaries without stream_end, ignoring any userId on the frame", async () => {
    const baseMs = Date.now() + 10_000;
    const inner = seededStore([
      {id: 'c1', userId: 'u1', at: isoAt(baseMs + 1_000), text: 'first'},
      {id: 'c2', userId: 'u1', at: isoAt(baseMs + 2_000), text: 'second'},
      {id: 'c3', userId: 'u1', at: isoAt(baseMs + 3_000), text: 'third'},
      {id: 'theirs', userId: 'u2', at: isoAt(baseMs + 4_000), text: 'other'},
    ]);
    const calls: RecordedCall[] = [];
    const store = recordingStore(inner, calls);
    const baseUrl = await startHalEngine(store, {resume: {enabled: true}, history: {enabled: true}});
    const {client} = await openAndGreet(`${baseUrl}?sessionId=c3`);

    const frames = await sendAndCollectUntilPong(client, [{type: 'list_conversations', userId: 'u2'}], 1);
    const listFrame = frames.find(frame => frame.type === 'conversation_list');
    const summaries = listFrame?.conversations ?? [];

    expect({
      types: frames.map(frame => frame.type),
      streamEnded: frames.some(frame => frame.type === 'stream_end'),
      ids: summaries.map(summary => summary.sessionId),
      shapes: summaries.map(summary => Object.keys(summary).sort()),
      isoValid: summaries.length === 3 && summaries.every(summaryHasIsoTimes),
      recordedCall: calls[0]
        ? {userId: calls[0].userId, limit: calls[0].options?.limit, before: calls[0].options?.before}
        : undefined,
    }).toEqual({
      types: ['conversation_list', 'pong'],
      streamEnded: false,
      ids: ['c3', 'c2', 'c1'],
      shapes: [
        ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
        ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
        ['createdAt', 'entryCount', 'sessionId', 'updatedAt'],
      ],
      isoValid: true,
      recordedCall: {userId: 'u1', limit: undefined, before: undefined},
    });
  });

  it('pages with limit and a composite before cursor, and lets a client resume any listed sessionId', async () => {
    const baseMs = Date.now() + 10_000;
    const tied = isoAt(baseMs + 2_000);
    const inner = seededStore([
      {id: 'c1', userId: 'u1', at: isoAt(baseMs + 1_000), text: 'remember 4711'},
      {id: 'c2', userId: 'u1', at: tied, text: 'second'},
      {id: 'c3', userId: 'u1', at: tied, text: 'third'},
    ]);
    const calls: RecordedCall[] = [];
    const store = recordingStore(inner, calls);
    const baseUrl = await startHalEngine(store, {resume: {enabled: true}, history: {enabled: true}});
    const {client} = await openAndGreet(`${baseUrl}?sessionId=c3`);

    const [page1] = await sendAndCollectUntilPong(client, [{type: 'list_conversations', limit: 2}], 1);
    const outcome = await continuePagingAndResume(client, baseUrl, page1);

    expect({
      page1Type: page1.type,
      page1Ids: page1.conversations?.map(summary => summary.sessionId),
      page2Ids: outcome.page2Ids,
      recordedOptions: calls.map(call => call.options),
      resumedConnected: outcome.resumedConnected,
      replayedContent: outcome.replayedContent,
    }).toEqual({
      page1Type: 'conversation_list',
      page1Ids: ['c3', 'c2'],
      page2Ids: ['c1'],
      recordedOptions: [
        {limit: 2, before: undefined},
        {limit: 2, before: {updatedAt: tied, sessionId: 'c2'}},
      ],
      resumedConnected: {sessionId: 'c1', resumed: true, entryCount: 1},
      replayedContent: 'remember 4711',
    });
  });

  it('answers list_conversations without waiting on a streaming turn, and rejects malformed limit or before with INVALID_MESSAGE', async () => {
    const {url, gate} = await startGatedStreamingServer();
    const {client, frames} = await openAndGreet(url);

    client.send(JSON.stringify({type: 'user_message', content: 'hello'}));
    await waitForFrame(frames, client, frame => frame.type === 'entry_delta');

    client.send(JSON.stringify({type: 'list_conversations'}));
    const midStream = await waitForFrame(
      frames,
      client,
      frame => frame.type === 'conversation_list' || frame.type === 'error'
    );
    const streamEndedBeforeReply = frames.some(frame => frame.type === 'stream_end');

    gate.release();
    await waitForFrame(frames, client, frame => frame.type === 'stream_end');

    const malformedPayloads = [
      {type: 'list_conversations', limit: 0},
      {type: 'list_conversations', limit: 201},
      {type: 'list_conversations', limit: 1.5},
      {type: 'list_conversations', limit: '10'},
      {type: 'list_conversations', before: {updatedAt: 'not-a-date', sessionId: 'c1'}},
      {type: 'list_conversations', before: {updatedAt: new Date(Date.now()).toISOString()}},
    ];
    const validationFrames = await sendAndCollectUntilPong(client, malformedPayloads, 8);
    const errorReplies = validationFrames.filter(frame => frame.type === 'error');

    expect({
      midStreamType: midStream.type,
      streamEndedBeforeReply,
      validationTypes: validationFrames.map(frame => frame.type),
      errorCodes: errorReplies.map(frame => frame.code),
      limitMessagesMentionField: errorReplies
        .slice(0, 4)
        .every(frame => /limit/i.test(frame.message ?? '')),
      beforeMessagesMentionField: errorReplies
        .slice(4, 6)
        .every(frame => /before/i.test(frame.message ?? '')),
    }).toEqual({
      midStreamType: 'conversation_list',
      streamEndedBeforeReply: false,
      validationTypes: ['error', 'error', 'error', 'error', 'error', 'error', 'pong'],
      errorCodes: [
        'INVALID_MESSAGE',
        'INVALID_MESSAGE',
        'INVALID_MESSAGE',
        'INVALID_MESSAGE',
        'INVALID_MESSAGE',
        'INVALID_MESSAGE',
      ],
      limitMessagesMentionField: true,
      beforeMessagesMentionField: true,
    });
  });

  it('refuses list_conversations with UNSUPPORTED when history is off, listFor is absent, or the store cannot list', async () => {
    const inner = new InMemorySessionStore();
    const fiveMemberStore: SessionStore = {
      create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
      get: sessionId => inner.get(sessionId),
      delete: sessionId => inner.delete(sessionId),
      count: () => inner.count(),
      clear: () => inner.clear(),
    };
    const brokenMongo = new MongoSessionStore({collection: fakeCollection()});

    const historyAbsent = await queryUnsupported(inner, undefined);
    const methodAbsent = await queryUnsupported(fiveMemberStore, {enabled: true});
    const collectionWithoutFind = await queryUnsupported(brokenMongo, {enabled: true});

    expect({historyAbsent, methodAbsent, collectionWithoutFind}).toEqual({
      historyAbsent: [{type: 'error', code: 'UNSUPPORTED'}, {type: 'pong', timestamp: 9}],
      methodAbsent: [{type: 'error', code: 'UNSUPPORTED'}, {type: 'pong', timestamp: 9}],
      collectionWithoutFind: [{type: 'error', code: 'UNSUPPORTED'}, {type: 'pong', timestamp: 9}],
    });
  });

  it('answers a rejecting listFor with SERVER_ERROR hiding store details, keeps the socket open, and logs the sessionId', async () => {
    const logged: Array<Record<string, unknown>> = [];
    const record = (level: string) => (category: string, message: string, fields?: Record<string, unknown>) =>
      void logged.push({level, category, message, ...fields});
    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});

    const inner = seededStore([{id: 's-priv', userId: 'u1', at: isoAt(Date.now()), text: 'private user content'}]);
    const failingStore: SessionStore = {
      create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
      get: sessionId => inner.get(sessionId),
      delete: sessionId => inner.delete(sessionId),
      count: () => inner.count(),
      clear: () => inner.clear(),
      listFor: () => Promise.reject(new Error('mongodb://admin:topsecret@db.internal:27017 timed out')),
    };

    const baseUrl = await startHalEngine(failingStore, {resume: {enabled: true}, history: {enabled: true}});
    const {client, greeting} = await openAndGreet(`${baseUrl}?sessionId=s-priv`);
    const frames = await sendAndCollectUntilPong(client, [{type: 'list_conversations'}], 42);
    const errorFrame = frames.find(frame => frame.type === 'error');
    const pongFrame = frames.find(frame => frame.type === 'pong');
    const errorLogs = logged.filter(entry => entry.level === 'error');

    expect({
      errorCode: errorFrame?.code,
      leakedStoreDetail:
        /topsecret|db\.internal|timed out/i.test(errorFrame?.message ?? '') ||
        JSON.stringify(errorLogs).includes('topsecret'),
      leakedUserContent: JSON.stringify(errorLogs).includes('private user content'),
      loggedWithSessionId: errorLogs.some(entry => entry.sessionId === greeting.sessionId),
      pongTimestamp: pongFrame?.timestamp,
    }).toEqual({
      errorCode: 'SERVER_ERROR',
      leakedStoreDetail: false,
      leakedUserContent: false,
      loggedWithSessionId: true,
      pongTimestamp: 42,
    });
  });
});

async function stopAll(): Promise<void> {
  await stopEngines();
  for (const engine of engines.splice(0)) await engine.stop();
}

function isoAt(ms: number): string {
  return new Date(ms).toISOString();
}

function seededStore(
  conversations: Array<{id: string; userId: string; at: string; text: string}>
): InMemorySessionStore {
  const store = new InMemorySessionStore();
  for (const conv of conversations) {
    const session = store.create(conv.id, conv.userId);
    session.entries.push({role: 'user', content: conv.text, timestamp: conv.at});
  }
  return store;
}

function recordingStore(inner: InMemorySessionStore, calls: RecordedCall[]): SessionStore {
  return {
    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
    get: sessionId => inner.get(sessionId),
    delete: sessionId => inner.delete(sessionId),
    count: () => inner.count(),
    clear: () => inner.clear(),
    lookup: sessionId => inner.lookup(sessionId),
    latestFor: userId => inner.latestFor(userId),
    listFor: (userId, options) => {
      calls.push({userId, options});
      return inner.listFor(userId, options);
    },
  };
}

async function startHalEngine(
  session: SessionStore,
  extraTransport: {resume?: {enabled: boolean}; history?: {enabled: boolean}}
): Promise<string> {
  const transport = {port: 0, ...extraTransport} as HalEngineConfig['transport'];
  const engine = createHalEngine({
    provider: {type: 'mock'},
    prompt: {identity: 'Conversation list acceptance test.'},
    auth: {ws: async () => ({id: 'u1'})},
    session,
    transport,
  });
  await engine.start(0);
  engines.push(engine);
  const {port} = engine.server.address() as AddressInfo;
  return `ws://127.0.0.1:${port}/hal/ws`;
}

